mutations.before:
if (typeof rights.licenceId !== "string" || rights.licenceId === "") {
  throw new Error('Campaign brief field "audio.rights.licenceId" must be a non-empty string.');
}

if (expiredAsset) {
  return err(
    new Error(
      `Asset ${assetIdentity(expiredAsset)} has a music licence ("${expiredAsset.audioRights?.licenceId}") that expired before this package's packagedAt.`,
    ),
  );
}

if (!territoryCovered(brief.targetRegion, rights.territories)) {
  log.record(
    "ExecuteLegalGateCheck",
    `Pipeline halted — music licence "${rights.licenceId}" does not cover territory "${brief.targetRegion}"`,
    "error",
  );
  log.complete();
  return true;
}
